import logging
from taf.transport.ssh import ssh
from .swhandler import SwHandler

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())
connection = ssh()


class swm(object):
    """
    This Library pilot the software management API of Netact : swmCLI API

    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 2

    def __init__(self):
        self.ROBOT_LIBRARY_LISTENER = self
        self._swhandler = SwHandler()
        self._session = None
        self._alias = 'Netact'
        self._sw_version = None

    def connect(self, hostname, username='omc', password=None):
        """
        To run the command log in to a virtual machine, where the was -<nodename> service is running.
        For more information, see locating the right virtual machine for a service administering
        NetAct Virtual Infrastructure

        :param hostname: Str: IP Address of NetAct VM adminstering SWM API
        :param username: Str: username for ssh session, By default fixed to 'omc'
        :param password: Str: password for ssh session, By default fixed to None

        :return: ssh session
        """
        self._hostname = hostname
        self._username = username
        self._password = password
        self._session = connection.connect_to(self._hostname, self._username, self._password, alias=self._alias)
        logger.info('connection established')
        return self._session

    def get_status(self, mo_id):
        """
        get current status of network elements

        :param mo_id(String): MRBTS Identifier e.g MRBTS-123

        :return: a string of following columns :
        MO_DN: Managed Object Distinguish name
        MO_NAME: Name of Managed Object
        RELEASE: Release of Managed Object
        ACTIVE_SW: software ID of active software on Managed Object
        PASSIVE_SW: Software ID of passive software on Managed Object
        PLANNED_SW: Software ID of planned software on Managed Object
        LAST_UPLOAD: Date of the last successful upload operation on Managed Object
        LAST_ACTIVE_OP: Type of the last active operation performed
        LAST_OP_STATUS: Status of the last operation on Managed Object
        """
        __command = 'swmCLI.sh mo-status -dn PLMN-PLMN/{}'.format(mo_id)
        return connection.execute(__command, self._alias)

    def do_action(self, action_type, mo_id, sw=None):
        """Private function"""
        if sw is None:
            __command = 'swmCLI.sh -op start --type {} -dn PLMN-PLMN/{}'.format(action_type, mo_id)
        else:
            __command = 'swmCLI.sh -op start --type {} -s {} -dn PLMN-PLMN/{}'.format(action_type, sw, mo_id)
        return connection.execute(__command, self._alias)

    def upload(self, mo_id):
        """
        upload to NetAct current BTS configuration infos e.g current sw versions....

        :param mo_id: Str: MRBTS Identifier e.g MRBTS-123

        :return: ID of the upload operation
        """
        return self.do_action('upload', mo_id)

    def cancel_action(self, ID):
        """
        cancel current operation e.g download, provision, rollback ...

        :param ID: Str: ID of the operation

        :return:
        """
        _command = 'swmCLI.sh -op cancel -id {}'.format(ID)
        return connection.execute(_command, self._alias)

    def is_operation_done(self, ID):
        """
        get an operation status

        :param ID: Str: ID of the operation

        :return: a bool based on the presence of the operation among current operations
        """
        _command = 'swmCLI.sh -op ongoing-operations'
        operations = connection.execute(_command, self._alias)
        return ID not in operations

    def import_file(self, sw, mo_type='MRBTS'):
        """
        import a software package stored in software temporary directory to NetAct archive directory

        :param sw: Str: sw file name e.g AirScale-5.8335.162.zip
        :param mo_type: Str: BTS Identifier e.g MRBTS

        :return: ID of the operation
        """
        _command = 'swmCLI.sh import --file {} --mo-type {}'.format(sw, mo_type)
        return connection.execute(_command, self._alias)

    def download(self, mo_id, sw_version):
        """
        download software version for a BTS

        :param mo_id: Str: identifier of MRBTS e.g MBTS-12345
        :param sw_version: Str: sw to be downloaded e.g 5.3835.765

        :return: ID of the operation
        """
        return self.do_action('download', mo_id, sw_version)

    def activate(self, mo_id, sw_version):
        """
        activate a version of software for a BTS

        :param mo_id: Str: identifier of MRBTS e.g MBTS-12345
        :param sw_version: Str: sw to be downloaded e.g FL16_ENB_0000_001454_00005

        :return: ID of the operation
        """
        return self.do_action('activation', mo_id, sw_version)

    def provision(self, mo_id, sw_version):
        """
        provision bts with specified version

        :param mo_id: Str: identifier of MRBTS e.g MBTS-12345
        :param sw_version: Str: sw to be downloaded e.g AirScale-5.3835.972

        :return: ID of the operation
        """
        return self.do_action('provision', mo_id, sw_version)

    def rollback(self, mo_id):
        """
        rollback to ancient software version

        :param mo_id: Str: identifier of MRBTS e.g MBTS-12345

        :return: ID of the operation
        """
        return self.do_action('rollback', mo_id)

    def disconnect(self):
        """
        Close current connection

        :return:
        """
        return connection.disconnect(self._alias)

    def get_sw_versions(self, mo_id):
        """
        get the software versions in netact, provided that netact is properly initialized

        if the value returned is blank you need to do call upload function before.
        :param mo_id: Str: BTS identifier like MRBTS-123

        :return: a dictionary of passive and active sw versions
        Example: {'ACTIVE_SW':'5.3853.85','PASSIVE_SW':'5.3867.76'}
        """
        values = self.get_status(mo_id)
        values_list = [[value.replace(" ", '') for value in vals.split(',')] for vals in values.split('\n')]
        return {values_list[0][3]: values_list[1][3], values_list[0][4]: values_list[1][4]}

    def get_last_sw_operation_info(self, mo_id):
        """
        get the last active software operation name and status

        :param mo_id: Str: MRBTS Identifer e.g MRBTS-12345

        :return: a dictionary of containing the name of the last software operation + status
        Example: {'LAST_ACTIVE_OP' : "SwUpload", "LAST_OP_STATUS": "success"}

        """
        values = self.get_status(mo_id)
        values_list = [[value.replace(" ", '') for value in vals.strip('\r').split(',')] for vals in values.split('\n')]
        return {values_list[0][-2]: values_list[1][-2], values_list[0][-1]: values_list[1][-1]}

    def sw_file_exists(self, file):
        """
        check if software file exists in NetAct Archive directory

        :param file: Str: name of the file e.g AirScal-5.3835.162

        :return: bool result
        """
        output = connection.execute('ls /var/opt/nokia/oss/global/swm/swm_arch', self._alias)
        if file in output:
            logger.info('software file already stored in netact')
            return True
        else:
            logger.info('software file not in package path')
            return False

    def add_sw_to_archive_storage(self, version, host_directory):
        """
        Add a software Build to netact software Archive directory
        this function download Build from artifactory, add it to NetAct Temporary storage and
        import it to NetAct Archive directory

        :param version: Str: software version should respect the from e.g 5.3851.321
        :param host_directory: Str: the directory on which you want to download the Build zip file

        :return: the file imported to NetAct
        """
        mo = 'MRBTS'
        remote_path = '/d/oss/global/swmanager/swm_temp'
        if self.sw_file_exists('AirScale-' + version):
            return
        else:
            self._swhandler.download_build_from_wft(version, host_directory)
            path_to_file = str(host_directory) + 'AirScale-' + str(version) + '.zip'
            self._swhandler.send_build_to_remote(self._hostname, self._username, self._password, path_to_file,
                                                 remote_path)
            logger.info('software file added to temporary directory')

        return self.import_file('AirScale-' + str(version) + '.zip', mo)
